const j = $input.first().json;
if (!j.image_base64) throw new Error('No image received from main workflow');
if (!j.provider?.space_url) throw new Error('No provider settings received from main workflow');
const mime = j.mime_type ?? 'image/jpeg';
const ext = (mime.split('/')[1] ?? 'jpg').replace('jpeg', 'jpg');
return [{
  json: { prompt: j.prompt, provider: j.provider },
  binary: { files: { data: j.image_base64, mimeType: mime, fileName: `input.${ext}` } },
}];

const prep = $('Prepare Upload').first().json;
let paths;
try { paths = JSON.parse($json.body); }
catch { throw new Error(`Image upload to the Space failed: ${String($json.body).slice(0, 200)}`); }
const path = Array.isArray(paths) ? paths[0] : null;
if (!path) throw new Error('Image upload to the Space returned no file path');

const image = { path, meta: { _type: 'gradio.FileData' } };
const data = prep.provider.data.map((v) => v === '__IMAGE__' ? image : v === '__PROMPT__' ? prep.prompt : v);
return [{ json: { body: { data }, provider: prep.provider } }];

// The Gradio result comes back as a server-sent-event stream: "event: X" / "data: Y" lines.
const prov = $('Build Call').first().json.provider;
const eventId = $('Start Job').first().json.event_id;
const raw = String($json.body ?? '');

const events = [];
let cur = null;
for (const line of raw.split(/\r?\n/)) {
  if (line.startsWith('event:')) { cur = { event: line.slice(6).trim(), data: '' }; events.push(cur); }
  else if (line.startsWith('data:') && cur) { cur.data += line.slice(5).trim(); }
}
const last = events.filter((e) => e.event === 'complete' || e.event === 'error').pop();
if (!last) throw new Error(`${prov.name}: no result from Space (${raw.slice(0, 150) || 'empty response'})`);

if (last.event === 'error') {
  let msg = last.data;
  try { const p = JSON.parse(last.data); msg = p?.message ?? p; } catch {}
  throw new Error(`${prov.name}: ${msg || 'the Space returned an error (it may be busy or out of GPU quota)'}`);
}

const out = JSON.parse(last.data);
const first = Array.isArray(out) ? out[0] : out;
const file = first?.video ?? first;           // Gradio video output may be wrapped in { video, subtitles }
let url = file?.url ?? null;
if (!url && file?.path) url = `${prov.space_url}/gradio_api/file=${file.path}`;
if (!url) throw new Error(`${prov.name}: finished but returned no video`);

return [{ json: { video_url: url, provider: prov.name, job_id: eventId } }];
